/* ===== helpers ===== */
var R=function(a,b){return a+Math.floor(Math.random()*(b-a+1));};
var pick=function(a){return a[R(0,a.length-1)];};
var shuffle=function(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=R(0,i);var t=a[i];a[i]=a[j];a[j]=t;}return a;};
var rep=function(v,n){var a=[];for(var i=0;i<n;i++)a.push(v);return a;};
var uniq=function(arr){var o=[],s={};arr.forEach(function(x){var k=String(x);if(!s[k]){s[k]=1;o.push(x);}});return o;};
var near=function(ans,n,min,max){var out=[],tries=0;min=(min===undefined)?0:min;max=(max===undefined)?ans+10:max;
  while(out.length<n&&tries<200){tries++;var d=ans+pick([-3,-2,-1,1,2,3,-10,10]);if(d!==ans&&d>=min&&d<=max&&out.indexOf(d)<0)out.push(d);}
  var k=1;while(out.length<n){var v=ans+k*7;if(v>=min&&out.indexOf(v)<0)out.push(v);k++;if(k>50)break;}return out;};
var fmt=function(n){return Number(n).toLocaleString("en-US");};
var gcd=function(a,b){return b?gcd(b,a%b):a;};
var red=function(n,d){var g=gcd(n,d);return [n/g,d/g];};
var fr=function(n,d){var r=red(n,d);return r[1]===1?String(r[0]):r[0]+"/"+r[1];};
var NAMES=["Ana","Luis","Mia","Diego","Sofia","Mateo","Camila","Jose","Valeria","Santiago","Elena","Marco"];
var THINGS=["apples","stickers","marbles","crayons","cookies","books","toy cars","shells","pencils","balloons"];
var num=function(q,a,hint,explain,vis){return {type:"num",q:q,a:String(a),hint:hint,explain:explain,vis:vis||""};};
var mc=function(q,a,wrong,hint,explain,vis){var ch=uniq([a].concat(wrong)).slice(0,4);return {type:"mc",q:q,a:String(a),choices:shuffle(ch).map(String),hint:hint,explain:explain,vis:vis||""};};

/* ===== SVG builders ===== */
var C={dot:"#7B61FF",alt:"#FF6B54",ink:"#21243D",line:"#B8C0D6",gold:"#FFC93C",mint:"#20B486",soft:"#EEF2FA"};
function svg(w,h,inner){return '<svg viewBox="0 0 '+w+' '+h+'" width="'+w+'" height="'+h+'" role="img" xmlns="http://www.w3.org/2000/svg">'+inner+'</svg>';}
function dots(n,frame,color){color=color||C.dot;var s="";
  if(frame==="ten"){var frames=Math.ceil(Math.max(n,1)/10);var w=frames*170;
    for(var f=0;f<frames;f++){for(var i=0;i<10;i++){var x=f*170+(i%5)*32+8,y=Math.floor(i/5)*32+8;
      s+='<rect x="'+x+'" y="'+y+'" width="30" height="30" fill="#fff" stroke="'+C.line+'" stroke-width="2"/>';
      if(f*10+i<n)s+='<circle cx="'+(x+15)+'" cy="'+(y+15)+'" r="10" fill="'+color+'"/>';}}
    return svg(w,72,s);}
  if(frame==="scatter"){var pts=[];var tries=0;while(pts.length<n&&tries<500){tries++;var x=R(12,208),y=R(12,88),ok=true;
      for(var k=0;k<pts.length;k++){if(Math.abs(pts[k][0]-x)<22&&Math.abs(pts[k][1]-y)<22){ok=false;break;}}if(ok)pts.push([x,y]);}
    pts.forEach(function(p){s+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="9" fill="'+color+'"/>';});return svg(220,100,s);}
  var per=10,rows=Math.ceil(n/per);for(var i2=0;i2<n;i2++){s+='<circle cx="'+((i2%per)*24+12)+'" cy="'+(Math.floor(i2/per)*24+12)+'" r="9" fill="'+color+'"/>';}
  return svg(per*24,rows*24,s);}
function twoGroups(a,b,la,lb){return '<div class="two"><div><b>'+la+'</b>'+dots(a,"row")+'</div><div><b>'+lb+'</b>'+dots(b,"row",C.alt)+'</div></div>';}
function bars(a,b,la,lb){var s='<rect x="10" y="12" width="'+(a*22)+'" height="20" fill="'+C.dot+'" rx="4"/><text x="10" y="50" font-size="13" font-family="sans-serif">'+la+'</text>'+
  '<rect x="10" y="66" width="'+(b*22)+'" height="20" fill="'+C.alt+'" rx="4"/><text x="10" y="104" font-size="13" font-family="sans-serif">'+lb+'</text>';return svg(260,110,s);}
function ruler(units,len){var s='<rect x="10" y="10" width="'+(len*24)+'" height="18" fill="'+C.gold+'" rx="3"/>';
  for(var i=0;i<=units;i++){s+='<line x1="'+(10+i*24)+'" y1="34" x2="'+(10+i*24)+'" y2="52" stroke="'+C.ink+'" stroke-width="2"/><text x="'+(10+i*24)+'" y="66" font-size="11" text-anchor="middle" font-family="sans-serif">'+i+'</text>';}
  s+='<line x1="10" y1="34" x2="'+(10+units*24)+'" y2="34" stroke="'+C.ink+'" stroke-width="2"/>';return svg(units*24+20,72,s);}
function clock(h,m){var s='<circle cx="60" cy="60" r="54" fill="#fff" stroke="'+C.ink+'" stroke-width="3"/>';
  for(var i=0;i<12;i++){var a=i*30*Math.PI/180;var x=60+46*Math.sin(a),y=60-46*Math.cos(a);s+='<text x="'+x+'" y="'+(y+4)+'" font-size="11" text-anchor="middle" font-family="sans-serif" font-weight="700">'+(i===0?12:i)+'</text>';}
  var ma=m*6*Math.PI/180,ha=((h%12)*30+m*0.5)*Math.PI/180;
  s+='<line x1="60" y1="60" x2="'+(60+26*Math.sin(ha))+'" y2="'+(60-26*Math.cos(ha))+'" stroke="'+C.ink+'" stroke-width="5" stroke-linecap="round"/>';
  s+='<line x1="60" y1="60" x2="'+(60+40*Math.sin(ma))+'" y2="'+(60-40*Math.cos(ma))+'" stroke="'+C.alt+'" stroke-width="3" stroke-linecap="round"/><circle cx="60" cy="60" r="3" fill="'+C.ink+'"/>';
  return svg(120,120,s);}
function barGraph(cats,vals,interval,title){var maxv=Math.max.apply(null,vals);var top=Math.ceil(maxv/interval)*interval||interval;var H=150,W=60+cats.length*70;var s='<text x="'+(W/2)+'" y="14" font-size="12" text-anchor="middle" font-family="sans-serif" font-weight="700">'+(title||"")+'</text>';
  for(var g=0;g<=top;g+=interval){var y=H-20-(g/top)*110;s+='<line x1="45" y1="'+y+'" x2="'+(W-5)+'" y2="'+y+'" stroke="'+C.line+'"/><text x="40" y="'+(y+4)+'" font-size="10" text-anchor="end" font-family="sans-serif">'+g+'</text>';}
  cats.forEach(function(c,i){var bh=(vals[i]/top)*110,x=60+i*70;s+='<rect x="'+x+'" y="'+(H-20-bh)+'" width="44" height="'+bh+'" fill="'+[C.dot,C.alt,C.mint,C.gold][i%4]+'"/><text x="'+(x+22)+'" y="'+(H-6)+'" font-size="11" text-anchor="middle" font-family="sans-serif">'+c+'</text>';});
  return svg(W,H,s);}
function picto(cats,vals,each){var s="";var W=110+Math.max.apply(null,vals)/each*22+20;cats.forEach(function(c,i){var y=i*30+22;s+='<text x="8" y="'+y+'" font-size="12" font-family="sans-serif" font-weight="700">'+c+'</text>';for(var k=0;k<vals[i]/each;k++){s+='<text x="'+(90+k*22)+'" y="'+(y+2)+'" font-size="18" fill="'+C.gold+'">&#9733;</text>';}});
  s+='<text x="8" y="'+(cats.length*30+22)+'" font-size="11" font-family="sans-serif">Key: &#9733; = '+each+'</text>';return svg(Math.max(W,220),cats.length*30+34,s);}
function nline(min,max,step,point,labelEvery){var n=(max-min)/step;var W=40+n*Math.min(40,Math.floor(400/n));var gap=(W-40)/n;var s='<line x1="20" y1="30" x2="'+(W-20)+'" y2="30" stroke="'+C.ink+'" stroke-width="2"/>';labelEvery=labelEvery||1;
  for(var i=0;i<=n;i++){var x=20+i*gap;s+='<line x1="'+x+'" y1="24" x2="'+x+'" y2="36" stroke="'+C.ink+'" stroke-width="2"/>';if(i%labelEvery===0)s+='<text x="'+x+'" y="52" font-size="11" text-anchor="middle" font-family="sans-serif">'+(min+i*step)+'</text>';}
  if(point!==undefined){var px=20+((point-min)/step)*gap;s+='<circle cx="'+px+'" cy="30" r="7" fill="'+C.alt+'"/><text x="'+px+'" y="16" font-size="12" text-anchor="middle" font-family="sans-serif" font-weight="700">?</text>';}
  return svg(W,58,s);}
var SHAPES={circle:'<circle cx="50" cy="50" r="40"/>',triangle:'<polygon points="50,10 90,90 10,90"/>',rectangle:'<rect x="8" y="25" width="84" height="50"/>',square:'<rect x="15" y="15" width="70" height="70"/>',
  rhombus:'<polygon points="50,8 92,50 50,92 8,50"/>',hexagon:'<polygon points="30,10 70,10 92,50 70,90 30,90 8,50"/>',pentagon:'<polygon points="50,8 92,40 76,90 24,90 8,40"/>',trapezoid:'<polygon points="25,20 75,20 95,80 5,80"/>',
  octagon:'<polygon points="35,8 65,8 92,35 92,65 65,92 35,92 8,65 8,35"/>',parallelogram:'<polygon points="25,25 95,25 75,75 5,75"/>'};
var SIDES={circle:0,triangle:3,rectangle:4,square:4,rhombus:4,hexagon:6,pentagon:5,trapezoid:4,octagon:8,parallelogram:4};
function shape2d(name,color){return svg(100,100,'<g fill="'+(color||C.soft)+'" stroke="'+C.ink+'" stroke-width="3">'+SHAPES[name]+'</g>');}
var SOLIDS={cube:'<polygon points="20,35 60,35 60,75 20,75" fill="#EEF2FA"/><polygon points="20,35 40,20 80,20 60,35" fill="#D9E0F2"/><polygon points="60,35 80,20 80,60 60,75" fill="#C5CEE8"/>',
  sphere:'<circle cx="50" cy="50" r="34" fill="#D9E0F2"/><ellipse cx="50" cy="50" rx="34" ry="12" fill="none" stroke-dasharray="4"/>',
  cylinder:'<ellipse cx="50" cy="22" rx="30" ry="10" fill="#D9E0F2"/><rect x="20" y="22" width="60" height="50" fill="#EEF2FA" stroke="none"/><line x1="20" y1="22" x2="20" y2="72"/><line x1="80" y1="22" x2="80" y2="72"/><path d="M20 72 A30 10 0 0 0 80 72" fill="#EEF2FA"/>',
  cone:'<ellipse cx="50" cy="80" rx="30" ry="10" fill="#D9E0F2"/><polygon points="20,80 50,10 80,80" fill="#EEF2FA"/>',
  "rectangular prism":'<polygon points="12,40 62,40 62,80 12,80" fill="#EEF2FA"/><polygon points="12,40 32,22 82,22 62,40" fill="#D9E0F2"/><polygon points="62,40 82,22 82,62 62,80" fill="#C5CEE8"/>',
  "triangular prism":'<polygon points="15,80 50,25 85,80" fill="#EEF2FA"/><polygon points="50,25 70,12 105,67 85,80" fill="#C5CEE8"/><line x1="15" y1="80" x2="35" y2="67"/><line x1="35" y1="67" x2="105" y2="67" stroke-dasharray="4"/>'};
function solid(name){return svg(110,100,'<g stroke="'+C.ink+'" stroke-width="2">'+SOLIDS[name]+'</g>');}
function coin(name){var v={penny:"1&cent;",nickel:"5&cent;",dime:"10&cent;",quarter:"25&cent;"}[name],r={penny:19,nickel:21,dime:17,quarter:24}[name],col=name==="penny"?"#C98A4B":"#C9CDD6";
  return svg(52,52,'<circle cx="26" cy="26" r="'+r+'" fill="'+col+'" stroke="'+C.ink+'" stroke-width="2"/><text x="26" y="31" font-size="12" text-anchor="middle" font-family="sans-serif" font-weight="700">'+v+'</text>');}
function coins(list){return '<div class="coins">'+list.map(coin).join("")+'</div>';}
function array2(r,c){var s="";for(var i=0;i<r;i++)for(var j=0;j<c;j++)s+='<circle cx="'+(j*24+12)+'" cy="'+(i*24+12)+'" r="8" fill="'+C.dot+'"/>';return svg(c*24,r*24,s);}
function gridRect(w,h,labels){var s="";for(var i=0;i<h;i++)for(var j=0;j<w;j++)s+='<rect x="'+(j*22+1)+'" y="'+(i*22+1)+'" width="22" height="22" fill="'+C.gold+'" stroke="#fff" stroke-width="2"/>';
  if(labels)s+='<text x="'+(w*11)+'" y="'+(h*22+16)+'" font-size="12" text-anchor="middle" font-family="sans-serif">'+w+'</text><text x="'+(w*22+14)+'" y="'+(h*11+4)+'" font-size="12" font-family="sans-serif">'+h+'</text>';
  return svg(w*22+30,h*22+22,s);}
function lshape(a,b,c,d){/* big rect a x b with c x d removed from top-right */var s="";for(var i=0;i<b;i++)for(var j=0;j<a;j++){if(i<d&&j>=a-c)continue;s+='<rect x="'+(j*20+1)+'" y="'+(i*20+1)+'" width="20" height="20" fill="'+C.gold+'" stroke="#fff" stroke-width="2"/>';}
  s+='<text x="'+(a*10)+'" y="'+(b*20+16)+'" font-size="11" text-anchor="middle" font-family="sans-serif">'+a+'</text><text x="'+(a*20+12)+'" y="'+(b*10)+'" font-size="11" font-family="sans-serif">'+(b-d)+'</text><text x="-14" y="'+(b*10)+'" font-size="11" font-family="sans-serif">'+b+'</text><text x="'+((a-c/2)*20)+'" y="-4" font-size="11" text-anchor="middle" font-family="sans-serif">'+c+'</text>';
  return '<svg viewBox="-24 -16 '+(a*20+50)+' '+(b*20+40)+'" width="'+(a*20+50)+'" height="'+(b*20+40)+'" xmlns="http://www.w3.org/2000/svg">'+s+'</svg>';}
function strip(den,shaded){var w=240/den,s="";for(var i=0;i<den;i++)s+='<rect x="'+(i*w+2)+'" y="2" width="'+w+'" height="40" fill="'+(i<shaded?C.dot:"#fff")+'" stroke="'+C.ink+'" stroke-width="2"/>';return svg(246,46,s);}
function partition(parts,equal){var s='<rect x="2" y="2" width="200" height="90" fill="'+C.soft+'" stroke="'+C.ink+'" stroke-width="3"/>';
  if(equal){for(var i=1;i<parts;i++)s+='<line x1="'+(2+i*200/parts)+'" y1="2" x2="'+(2+i*200/parts)+'" y2="92" stroke="'+C.ink+'" stroke-width="3"/>';}
  else{var xs=[0];var acc=0;for(var k=1;k<parts;k++){acc+=200/parts*(k%2?0.55:1.45);xs.push(acc);}for(var m=1;m<parts;m++)s+='<line x1="'+(2+Math.min(xs[m],195))+'" y1="2" x2="'+(2+Math.min(xs[m],195))+'" y2="92" stroke="'+C.ink+'" stroke-width="3"/>';}
  return svg(206,96,s);}
function decGrid(n,tenths){var s="";if(tenths){for(var i=0;i<10;i++)s+='<rect x="'+(i*20+1)+'" y="1" width="20" height="100" fill="'+(i<n?C.dot:"#fff")+'" stroke="'+C.ink+'"/>';return svg(204,104,s);}
  for(var k=0;k<100;k++){var r=Math.floor(k/10),c=k%10;s+='<rect x="'+(c*12+1)+'" y="'+(r*12+1)+'" width="12" height="12" fill="'+(k<n?C.dot:"#fff")+'" stroke="'+C.line+'"/>';}return svg(124,124,s);}
function angleSvg(deg){var a=deg*Math.PI/180;var x=30+90*Math.cos(a),y=110-90*Math.sin(a);return svg(140,120,'<line x1="30" y1="110" x2="130" y2="110" stroke="'+C.ink+'" stroke-width="3"/><line x1="30" y1="110" x2="'+x+'" y2="'+y+'" stroke="'+C.ink+'" stroke-width="3"/><path d="M60 110 A30 30 0 0 0 '+(30+30*Math.cos(a))+' '+(110-30*Math.sin(a))+'" fill="none" stroke="'+C.alt+'" stroke-width="3"/>');}
function coordSvg(x,y){var s="";for(var i=0;i<=10;i++){s+='<line x1="'+(20+i*20)+'" y1="20" x2="'+(20+i*20)+'" y2="220" stroke="'+C.line+'"/><line x1="20" y1="'+(20+i*20)+'" x2="220" y2="'+(20+i*20)+'" stroke="'+C.line+'"/>';
    s+='<text x="'+(20+i*20)+'" y="236" font-size="9" text-anchor="middle" font-family="sans-serif">'+i+'</text><text x="10" y="'+(224-i*20)+'" font-size="9" text-anchor="end" font-family="sans-serif">'+i+'</text>';}
  s+='<line x1="20" y1="220" x2="220" y2="220" stroke="'+C.ink+'" stroke-width="2"/><line x1="20" y1="20" x2="20" y2="220" stroke="'+C.ink+'" stroke-width="2"/>';
  if(x!==undefined)s+='<circle cx="'+(20+x*20)+'" cy="'+(220-y*20)+'" r="6" fill="'+C.alt+'"/>';return svg(240,240,s);}
function triSvg(deg){var a=deg*Math.PI/180;var L=110;var bx=20+L,by=120,cx=20+80*Math.cos(a),cy=120-80*Math.sin(a);
  return svg(160,130,'<polygon points="20,120 '+bx+','+by+' '+cx+','+cy+'" fill="'+C.soft+'" stroke="'+C.ink+'" stroke-width="3"/><text x="'+(20+34*Math.cos(a/2)+6)+'" y="'+(120-34*Math.sin(a/2)+4)+'" font-size="12" font-family="sans-serif" font-weight="700">'+deg+'&deg;</text>');}
function geomSvg(kind){var g='stroke="'+C.ink+'" stroke-width="3"';var m={
  line:'<line x1="10" y1="60" x2="150" y2="30" '+g+'/><polygon points="150,30 140,26 142,36" fill="'+C.ink+'"/><polygon points="10,60 20,64 18,54" fill="'+C.ink+'"/>',
  segment:'<line x1="20" y1="60" x2="140" y2="30" '+g+'/><circle cx="20" cy="60" r="5" fill="'+C.ink+'"/><circle cx="140" cy="30" r="5" fill="'+C.ink+'"/>',
  ray:'<line x1="20" y1="60" x2="150" y2="30" '+g+'/><circle cx="20" cy="60" r="5" fill="'+C.ink+'"/><polygon points="150,30 140,26 142,36" fill="'+C.ink+'"/>',
  "parallel lines":'<line x1="10" y1="30" x2="150" y2="30" '+g+'/><line x1="10" y1="70" x2="150" y2="70" '+g+'/>',
  "perpendicular lines":'<line x1="10" y1="80" x2="150" y2="80" '+g+'/><line x1="80" y1="10" x2="80" y2="80" '+g+'/><rect x="80" y="66" width="14" height="14" fill="none" '+g+' stroke-width="2"/>',
  angle:'<line x1="20" y1="80" x2="150" y2="80" '+g+'/><line x1="20" y1="80" x2="120" y2="15" '+g+'/>',
  point:'<circle cx="80" cy="50" r="6" fill="'+C.ink+'"/><text x="92" y="55" font-size="14" font-family="sans-serif">A</text>'};
  return svg(160,100,m[kind]);}

