GEN.wpadd=function(p){var max=p.max||10;var t=p.type==="mix"?pick(["join","sep","cmp"]):(p.type||"join");var n1=pick(NAMES),th=pick(THINGS);
  if(t==="join"){var a=R(1,max-1),b=R(1,max-a);return num(n1+" has "+a+" "+th+". "+n1+" gets "+b+" more. How many "+th+" now?",a+b,"Joining means add.",a+" + "+b+" = "+(a+b)+".");}
  if(t==="sep"){var c=R(2,max),d=R(1,c);return num(n1+" has "+c+" "+th+" and gives away "+d+". How many are left?",c-d,"Separating means subtract.",c+" &minus; "+d+" = "+(c-d)+".");}
  var e=R(1,max),f=R(1,max);while(f===e)f=R(1,max);var n2=pick(NAMES.filter(function(x){return x!==n1;}));return num(n1+" has "+e+" "+th+". "+n2+" has "+f+". How many more does "+(e>f?n1:n2)+" have?",Math.abs(e-f),"Compare means find the difference.",Math.max(e,f)+" &minus; "+Math.min(e,f)+" = "+Math.abs(e-f)+".");};
GEN.longer=function(p){var a=R(2,10),b=R(2,10);while(b===a)b=R(2,10);var w=pick(["longer","shorter"]);var ans=((a>b)===(w==="longer"))?"Bar A":"Bar B";return mc("Which bar is <b>"+w+"</b>?",ans,["Bar A","Bar B","Same length"],"Line up the left ends and compare.",ans+" is "+w+".",bars(a,b,"Bar A","Bar B"));};
GEN.holds=function(p){var a=R(2,6),b=R(2,6);while(b===a)b=R(2,6);var ans=a>b?"Container A":"Container B";var s='<rect x="20" y="'+(110-a*15)+'" width="60" height="'+(a*15)+'" fill="'+C.dot+'" stroke="'+C.ink+'"/><text x="50" y="128" font-size="12" text-anchor="middle" font-family="sans-serif">A</text><rect x="120" y="'+(110-b*15)+'" width="60" height="'+(b*15)+'" fill="'+C.alt+'" stroke="'+C.ink+'"/><text x="150" y="128" font-size="12" text-anchor="middle" font-family="sans-serif">B</text>';
  return mc("Which container holds <b>more</b>?",ans,["Container A","Container B","Same"],"Bigger containers hold more.",ans+" is bigger, so it holds more.",svg(200,134,s));};
GEN.pgraph=function(p){var cats=shuffle(["Dogs","Cats","Fish","Birds"]).slice(0,p.cats||3);var vals=cats.map(function(){return R(1,p.max||6);});var m=pick(["most","fewest","count"]);var v=picto(cats,vals,1);
  if(m==="count"){var i=R(0,cats.length-1);return num("How many "+cats[i].toLowerCase()+"?",vals[i],"Count the stars in that row.","The "+cats[i]+" row has "+vals[i]+" stars.",v);}
  var idx=vals.indexOf(m==="most"?Math.max.apply(null,vals):Math.min.apply(null,vals));var ties=vals.filter(function(x){return x===vals[idx];}).length;if(ties>1){vals[idx]+= (m==="most"?2:0); if(m==="fewest")vals[idx]=Math.max(1,vals[idx]-1); v=picto(cats,vals,1);}
  return mc("Which has the <b>"+m+"</b>?",cats[idx],cats.filter(function(c){return c!==cats[idx];}),"The longest row is the most. The shortest row is the fewest.",cats[idx]+" has the "+m+".",v);};
GEN.coinname=function(p){var c=pick(["penny","nickel","dime","quarter"]);return mc("What coin is this?",c,["penny","nickel","dime","quarter"],"Look at the size and the color.","This is a "+c+".",coin(c));};
GEN.skip=function(p){var step=p.step||pick([2,5,10]);var max=p.max||100;var start=step*R(1,Math.floor(max/step)-4);var seq=[start,start+step,start+2*step,start+3*step];var miss=R(1,3);var ans=seq[miss];seq[miss]="__";
  return num("Count by "+step+"s. Fill in the missing number: "+seq.join(", "),ans,"Add "+step+" each time.","The missing number is "+ans+".");};
