/* --- place value and comparing --- */
GEN.pv=function(p){var max=p.max||99,mode=p.mode||pick(["tens","digit","expanded","std"]);var n=R(10,max);var digits=String(n).split("").map(Number);var places=["ones","tens","hundreds","thousands","ten thousands","hundred thousands","millions","ten millions","hundred millions","billions"];
  if(mode==="tens"){var t=Math.floor(n/10)%10;return num("How many <b>tens</b> are in "+n+"?",t,"The tens digit is second from the right.",n+" has "+t+" tens and "+(n%10)+" ones.");}
  if(mode==="digit"){var cand=[];digits.forEach(function(x,k){if(x!==0&&digits.filter(function(y){return y===x;}).length===1)cand.push(k);});if(!cand.length)return GEN.pv({max:max,mode:"digit"});var i=pick(cand);var d=digits[i];var pl=places[digits.length-1-i];var val=d*Math.pow(10,digits.length-1-i);return num("What is the <b>value</b> of the digit "+d+" in "+fmt(n)+"?",val,"The "+d+" is in the "+pl+" place.","The "+d+" is in the "+pl+" place, so its value is "+fmt(val)+".");}
  if(mode==="expanded"){var parts=[];digits.forEach(function(d,i){var v=d*Math.pow(10,digits.length-1-i);if(v)parts.push(fmt(v));});var ans=parts.join(" + ");var w=[parts.slice().reverse().join(" + "),digits.join(" + "),parts.map(function(x){return fmt(Number(x.replace(/,/g,""))*10);}).join(" + ")];return mc("Which shows "+fmt(n)+" in <b>expanded form</b>?",ans,w,"Write the value of each digit.",fmt(n)+" = "+ans+".");}
  if(mode==="word"){var W=numWord(n);return mc("Which shows "+fmt(n)+" in <b>word form</b>?",W,[numWord(n+10>max?n-10:n+10),numWord(Number(String(n).split("").reverse().join(""))||n+1),numWord(n+1>max?n-1:n+1)],"Read the number aloud.",fmt(n)+" is written "+W+".");}
  var parts2=[];digits.forEach(function(d,i){var v=d*Math.pow(10,digits.length-1-i);if(v)parts2.push(fmt(v));});return num("What number is "+parts2.join(" + ")+"?",n,"Add the values.",parts2.join(" + ")+" = "+fmt(n)+".");};
function numWord(n){var ones=["","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"],tens=["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"];
  function u(x){if(x<20)return ones[x];var t=tens[Math.floor(x/10)],o=ones[x%10];return t+(o?"-"+o:"");}
  var s="";if(n>=1000){s+=u(Math.floor(n/1000))+" thousand";n%=1000;if(n)s+=" ";}if(n>=100){s+=u(Math.floor(n/100))+" hundred";n%=100;if(n)s+=" ";}if(n)s+=u(n);return s||"zero";}
GEN.cmpsym=function(p){return GEN.cmpnum({max:p.max||100,mode:"sym"});};
