GEN.facts=function(p){var max=p.max||20;var op=p.op==="mix"?pick(["+","-"]):(p.op||"+");if(op==="+"){var a=R(0,max),b=R(0,max-a);var h=(a+b>10&&a<10&&b<10)?"Make a ten first: "+a+" + "+(10-a)+" = 10, then add the rest.":"Count on from the bigger number.";return num(a+" + "+b+" = ?",a+b,h,a+" + "+b+" = "+(a+b)+".");}
  var c=R(0,max),d=R(0,c);return num(c+" &minus; "+d+" = ?",c-d,"Think addition: "+d+" + ? = "+c+".",c+" &minus; "+d+" = "+(c-d)+".");};
