wrapVis("wp2",function(q,p){var n=numsIn(q);if(n.length===2)return stripDiagram(q.q.indexOf("gave away")>0||q.q.indexOf("left")>0?[n[0]-n[1],n[1]]:[n[0],n[1]],q.q.indexOf("left")>0?["?",n[1]]:[n[0],n[1]],q.q.indexOf("left")>0?n[0]:"?");return "";});
wrapVis("pvbig",function(q,p){var n=numsIn(q);var big=n.filter(function(x){return x>=100;}).sort(function(a,b){return b-a;})[0];if(big&&p.mode!=="x10"&&p.mode!=="tenth")return pvChart(big);return "";});
wrapVis("unkfactor",function(q){var m=q.q.match(/: (.*)$/);if(!m)return "";var e=m[1].replace(/&divide;/g,"/");var a=e.match(/^(\S+) x (\S+) = (\S+)$/);if(a)return factTri(a[3],a[1],a[2]);var d=e.match(/^(\S+) \/ (\S+) = (\S+)$/);if(d)return factTri(d[1],d[2],d[3]);return "";});
wrapVis("mfacts",function(q,p){var n=numsIn(q);if(p.div&&n.length>=2)return factTri(n[0],n[1],"?");if(n.length===2&&n[0]<=10&&n[1]<=10)return array2(n[0],n[1]);return "";});
