wrapVis("fracsum",function(q){var m=q.q.match(/(\d+)\/(\d+)[^\d]+(\d+)\/(\d+)/);if(m)return strip(+m[2],+m[1])+strip(+m[4],+m[3]);return "";});
wrapVis("fracmult",function(q){var m=q.q.match(/(\d+) x (\d+)\/(\d+)/);if(m&&+m[1]<=6){var s="";for(var i=0;i<+m[1];i++)s+=strip(+m[3],+m[2]);return s;}return "";});
wrapVis("fracdiv",function(q){var m=q.q.match(/^(\d+) &divide; 1\/(\d+)/);if(m&&+m[1]<=6){var s="";for(var i=0;i<+m[1];i++)s+=strip(+m[2],+m[2]);return s;}var m2=q.q.match(/^1\/(\d+) &divide; (\d+)/);if(m2)return strip(+m2[1],1);return "";});
wrapVis("decimal",function(q,p){var n=numsIn(q);if(p.mode==="cmp"&&(p.places||2)===2&&n.length>=2&&n[0]<1&&n[1]<1)return decGrid(Math.round(n[0]*100),false)+decGrid(Math.round(n[1]*100),false);if(p.mode==="round"&&n.length){var x=n[0];var to=q.q.indexOf("tenth")>0?10:100;var lo=Math.floor(x*to)/to,hi=lo+1/to;return nline(0,10,1,Math.round((x-lo)*to*10),5).replace(/>(\d+)</g,function(m,d){return ">"+(lo+d/(10*to)).toFixed(to===10?2:3)+"<";});}return "";});
wrapVis("round",function(q){var n=numsIn(q);if(n.length>=2){var x=n[0],to=n[1];var lo=Math.floor(x/to)*to;return nline(lo,lo+to,to/10,x,5);}return "";});
wrapVis("pattern",function(q){var m=q.q.match(/y = (\d+)x|y = x \+ (\d+)/);if(!m)return "";var rows=[1,2,3].map(function(x){return "<tr><td>"+x+"</td><td>"+(m[1]?x*+m[1]:x+ +m[2])+"</td></tr>";}).join("");return '<table class="mini"><tr><th>x</th><th>y</th></tr>'+rows+'</table>';});
wrapVis("coord",function(q,p){if(p.mode==="plot")return coordSvg();return "";});
wrapVis("elapsed",function(q){var n=numsIn(q);if(n.length>=2)return nline(0,Math.ceil((n[0]+n[1])/15)*15,5,n[0],3);return "";});
wrapVis("decmult",function(q,p){if(p.mode==="money"){var n=numsIn(q);if(n.length>=2)return '<table class="mini"><tr><th>Item</th><th>Price</th><th>Qty</th></tr><tr><td>Ticket</td><td>$'+n[1].toFixed(2)+'</td><td>'+n[0]+'</td></tr></table>';}return "";});
wrapVis("budget",function(q){var n=numsIn(q);if(n.length>=4)return '<table class="mini"><tr><th>Income</th><td>$'+n[0]+'</td></tr><tr><th>Expense 1</th><td>$'+n[1]+'</td></tr><tr><th>Expense 2</th><td>$'+n[2]+'</td></tr><tr><th>Expense 3</th><td>$'+n[3]+'</td></tr></table>';return "";});
wrapVis("prime",function(q){var n=numsIn(q);if(n.length===1&&n[0]<=49){var v=n[0];var f=[];for(var i=2;i<v;i++)if(v%i===0)f.push(i);return f.length?array2(f[0],v/f[0]):dots(v,"row");}return "";});
wrapVis("cmpnum",function(q,p){var n=numsIn(q);if(p.mode==="sym"&&n.length===2&&Math.max(n[0],n[1])<=20)return twoGroups(n[0],n[1],String(n[0]),String(n[1]));return "";});
wrapVis("tenmore",function(q){var n=numsIn(q);if(n.length>=2&&n[1]<=120)return nline(Math.max(0,Math.floor(n[1]/10)*10-20),Math.floor(n[1]/10)*10+30,10,n[1],1);return "";});
wrapVis("order",function(q){var n=numsIn(q);if(n.length&&Math.max.apply(null,n)<=200)return nline(0,Math.ceil(Math.max.apply(null,n)/50)*50,10,undefined,5);return "";});
wrapVis("measwp",function(q){var n=numsIn(q);if(q.q.indexOf("feet")>0&&n.length)return ruler(n[0],n[0]);return "";});

/* ===== difficulty policy: level 1 basic, 2 core (the week's spec), 3 advanced, never above the grade ceiling ===== */
function lo(x,f){return Math.max(3,Math.ceil((x||10)*(f||0.6)));}
function cp(p,o){var r={};for(var k in p)r[k]=p[k];for(var k2 in o)r[k2]=o[k2];return r;}
var LVL={
 count:function(p,l){return l===1?cp(p,{max:(p.max||10)<=5?p.max:lo(p.max),frame:"row"}):l===3?cp(p,{frame:"scatter"}):p;},
 subit:function(p,l){return l===1?cp(p,{max:Math.min(p.max||6,4)}):p;},
 matchset:function(p,l){return l===1?cp(p,{max:(p.max||10)<=5?p.max:lo(p.max)}):p;},
 cmpsets:function(p,l){return l===1?cp(p,{max:lo(p.max),fewer:0}):l===3?cp(p,{fewer:R(0,1)}):p;},
 cmpnum:function(p,l){return l===1?cp(p,{max:lo(p.max,0.5)}):p;},
 onemore:function(p,l){return l===1?cp(p,{dir:"more",max:lo(p.max)}):l===3?cp(p,{dir:"both"}):p;},
 compose:function(p,l){return l===1?cp(p,{n:Math.max(3,(p.n||8)-2)}):p;},
 decomp:function(p,l){return l===1?cp(p,{n:Math.max(4,(p.n||8)-2)}):p;},
 shape2d:function(p,l){return l===1?cp(p,{forms:["name","pick"]}):l===3?cp(p,{forms:["real","sides","pick"]}):p;},
 countback:function(p,l){return l===1?cp(p,{max:lo(p.max,0.5)}):p;},
 add:function(p,l){return l===1?cp(p,{max:Math.min(p.max||10,5),vis:1}):l===3?cp(p,{vis:0}):p;},
 sub:function(p,l){return l===1?cp(p,{max:Math.min(p.max||10,5),vis:1}):l===3?cp(p,{vis:0}):p;},
 wpadd:function(p,l){return l===1?cp(p,{type:p.type==="mix"?"join":p.type,vis:1,unknown:"result"}):l===3?cp(p,{type:"mix",unknown:"any"}):p;},
 facts:function(p,l){return l===1?cp(p,{max:Math.min(p.max||20,10),vis:1}):l===3?cp(p,{max:20,op:"mix"}):p;},
 unknown:function(p,l){return l===1?cp(p,{max:Math.min(p.max||20,10)}):p;},
 addmulti:function(p,l){return l===1?cp(p,{max:lo(p.max,0.5),addends:2}):l===3?cp(p,{addends:Math.min(4,(p.addends||2)+1)}):p;},
 submulti:function(p,l){return l===1?cp(p,{max:lo(p.max,0.5),zero:0}):l===3?cp(p,{zero:(p.max||99)>=100?1:0}):p;},
 wp2:function(p,l){return l===1?cp(p,{steps:1,max:lo(p.max,0.5)}):l===3?cp(p,{steps:2}):p;},
 pv:function(p,l){return l===1?cp(p,{mode:(p.max||99)<=99?"tens":"std",vis:1}):l===3?cp(p,{mode:pick(["digit","expanded","word"])}):p;},
 pvbig:function(p,l){return l===1?cp(p,{max:Math.max(1000,Math.floor((p.max||100000)/100))}):p;},
 cmpsym:function(p,l){return l===1?cp(p,{max:lo(p.max,0.3)}):p;},
 order:function(p,l){return l===1?cp(p,{max:lo(p.max,0.3)}):p;},
 tenmore:function(p,l){return l===1?cp(p,{dir:"more"}):l===3?cp(p,{dir:"less"}):p;},
 nline:function(p,l){return l===1?cp(p,{max:p.min+((p.max-p.min)/2)}):p;},
 skip:function(p,l){return l===1?cp(p,{max:100}):l===3?cp(p,{max:120}):p;},
 clock:function(p,l){var o=["hour","half","five","minute"];var i=o.indexOf(p.mode||"hour");return l===1?cp(p,{mode:o[Math.max(0,i-1)]}):p;},
 coinval:function(p,l){return l===1?cp(p,{coins:(p.coins||["penny","dime"]).slice(0,2),count:3}):l===3?cp(p,{count:(p.count||5)+2}):p;},
 graph:function(p,l){return l===1?cp(p,{cats:3,ask:"count"}):l===3?cp(p,{cats:4,ask:"more"}):p;},
 pgraph:function(p,l){return l===1?cp(p,{cats:2}):l===3?cp(p,{cats:4}):p;},
 evenodd:function(p,l){return l===1?cp(p,{max:Math.min(p.max||40,20)}):p;},
 eqgroups:function(p,l){return l===1?cp(p,{max:3,form:"total"}):l===3?cp(p,{max:9}):p;},
 eqshares:function(p,l){return l===1?cp(p,{max:3}):l===3?cp(p,{max:9}):p;},
 area:function(p,l){return l===1?cp(p,{mode:"tile",max:6}):p;},
 perim:function(p,l){return l===1?cp(p,{mode:"find"}):l===3?cp(p,{mode:"missing"}):p;},
 fracid:function(p,l){return l===1?cp(p,{dens:[2,4]}):l===3?cp(p,{dens:[3,6,8]}):p;},
 fracline:function(p,l){return l===1?cp(p,{dens:[2,4]}):l===3?cp(p,{dens:[6,8]}):p;},
 fraccmp:function(p,l){return l===1?cp(p,{same:"den"}):l===3?cp(p,{same:"any"}):p;},
 mfacts:function(p,l){return l===1?cp(p,{max:5}):l===3?cp(p,{max:10}):p;},
 divide:function(p,l){return l===1?cp(p,{mode:"share"}):l===3?cp(p,{mode:"inverse"}):p;},
 mult2x1:function(p,l){return l===1?cp(p,{amin:11,amax:19,vis:1}):l===3?cp(p,{amin:50,amax:99}):p;},
 multbig:function(p,l){if(l===1)return cp(p,{kind:p.kind==="3x2"?"3x2":"2x2",small:1});if(l===3)return cp(p,{kind:p.kind==="4x1"?"2x2":"3x2",small:0});return p;},
 divrep:function(p,l){return p;},
 longdiv:function(p,l){return l===1?cp(p,{rem:0,qmax:p.divisor===2?40:0}):l===3?cp(p,{rem:1,qmax:p.divisor===2?99:0}):p;},
 decimal:function(p,l){return l===1?cp(p,{places:Math.min(p.places||2,2),mode:p.mode==="round"||p.mode==="order"?"cmp":p.mode}):l===3?cp(p,{places:p.places||2}):p;},
 adddec:function(p,l){return l===1?cp(p,{sub:0}):l===3?cp(p,{sub:1}):p;},
 fracsum:function(p,l){return l===1?cp(p,{like:1,sub:0,mix:0}):l===3?cp(p,{mix:1}):p;},
 oops:function(p,l){return l===1?cp(p,{levels:1}):l===3?cp(p,{levels:2}):p;},
 round:function(p,l){return l===1?cp(p,{to:10,max:999}):p;},
 multistep:function(p,l){return l===1?{gen:"wpmd",p:{steps:1}}:p;},
 wpmd:function(p,l){return l===1?cp(p,{steps:1}):l===3?cp(p,{steps:2}):p;},
 decmult:function(p,l){return l===1?cp(p,{mode:"model"}):l===3?cp(p,{mode:p.mode==="model"?"solve":"money"}):p;},
 decdiv:function(p,l){return l===1?cp(p,{mode:"model",divisor:1}):l===3?cp(p,{mode:"solve",divisor:2}):p;},
 volume:function(p,l){return l===1?cp(p,{mode:"cubes"}):l===3?cp(p,{mode:"formula"}):p;},
 angle:function(p,l){return l===1?cp(p,{mode:"estimate"}):l===3?cp(p,{mode:"adjacent"}):p;},
 coord:function(p,l){return l===1?cp(p,{mode:"plot"}):l===3?cp(p,{mode:"read"}):p;},
 unitmeas:function(p,l){return l===1?cp(p,{max:5}):p;},
 halves:function(p,l){return l===1?cp(p,{parts:2}):p;},
 unkfactor:function(p,l){return p;}
};
function levelSpec(spec,l){var g=spec[0],p=spec[1]||{};var f=LVL[g];if(!f)return [g,p];var r=f(p,l);if(r&&r.gen)return [r.gen,r.p];return [g,r];}
function sigOf(q){return (q.q+"|"+(q.vis||"")+"|"+q.a).replace(/\s+/g,"");}
/* build a set of unique questions; levels is an array of 1/2/3 the same length as count */
/* build a set of unique questions; levels is an array of 1/2/3 the same length as count.
   pool = wider list of specs (the rest of the week) used when a day's own specs run out of unique questions.
   Repeats are never returned: if the space is exhausted, the set comes back shorter with .short=true. */
function makeSet(specs,count,levels,pool){var out=[],seen={},aseen={};pool=pool||specs;
  for(var i=0;i<count;i++){var l=levels?levels[i]:2;var q=null;
    var lists=[specs,pool];for(var li=0;li<lists.length&&!q;li++){var src=lists[li];var order=[];for(var k=0;k<src.length;k++)order.push(src[(i+k)%src.length]);
      for(var oi=0;oi<order.length&&!q;oi++){var spec=order[oi];for(var t=0;t<(li===0?30:15);t++){var ls=levelSpec(spec,l);var c=GEN[ls[0]](ls[1]||{});c.gen=ls[0];c.lvl=l;var sig=sigOf(c);var ak=c.gen+"|"+c.a;
          if(seen[sig])continue;if(c.type==="mc"&&aseen[ak]&&t<10)continue;q=c;break;}}}
    if(!q){out.short=true;break;}seen[sigOf(q)]=1;aseen[q.gen+"|"+q.a]=1;out.push(q);}
  return out;}
function levelsFor(mode,count){var a=[];for(var i=0;i<count;i++){a.push(mode==="basic"?1:mode==="advanced"?3:mode==="mixed"?[1,2,3][i%3]:(i<count/3?1:i<2*count/3?2:3));}return mode==="mixed"?shuffle(a):a;}

